package com.medflow.lab;
import static org.hamcrest.Matchers.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.medflow.lab.client.ClinicalReferenceService;
import com.medflow.lab.entity.*;
import com.medflow.lab.exception.ApiException;
import com.medflow.lab.repository.*;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.security.Keys;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.*;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;
@SpringBootTest @AutoConfigureMockMvc
class LabApiTest {
    static final String SECRET="test-secret-that-is-at-least-thirty-two-bytes-long";
    @Autowired MockMvc mvc;@Autowired LabOrderRepository orders;@Autowired LabResultRepository results;
    @MockitoBean ClinicalReferenceService references;
    UUID patientUser,doctorUser,patientId,doctorId;
    @BeforeEach void clean(){results.deleteAll();orders.deleteAll();reset(references);patientUser=UUID.randomUUID();doctorUser=UUID.randomUUID();patientId=UUID.randomUUID();doctorId=UUID.randomUUID();when(references.patientProfileForCurrentUser(eq(patientUser),anyString())).thenReturn(patientId);when(references.doctorProfileForCurrentUser(eq(doctorUser),anyString())).thenReturn(doctorId);}
    @Test void healthIsPublicAndApiRequiresAuthentication()throws Exception{mvc.perform(get("/actuator/health")).andExpect(status().isOk());mvc.perform(get("/api/lab/orders/me")).andExpect(status().isUnauthorized());}
    @Test void patientCreatesOrderForOwnProfile()throws Exception{UUID appointment=UUID.randomUUID();String jwt=token(patientUser,"PATIENT");mvc.perform(post("/api/lab/orders").header("Authorization",jwt).contentType(MediaType.APPLICATION_JSON).content(orderJson(patientId,doctorId,appointment))).andExpect(status().isCreated()).andExpect(jsonPath("$.patientId").value(patientId.toString())).andExpect(jsonPath("$.doctorId").value(doctorId.toString())).andExpect(jsonPath("$.status").value("ORDERED"));verify(references).patientProfileForCurrentUser(patientUser,jwt);verify(references).validateOrderReferences(eq(appointment),eq(patientId),eq(doctorId),eq(jwt));}
    @Test void patientCannotCreateOrderForAnotherPatient()throws Exception{String jwt=token(patientUser,"PATIENT");mvc.perform(post("/api/lab/orders").header("Authorization",jwt).contentType(MediaType.APPLICATION_JSON).content(orderJson(UUID.randomUUID(),doctorId,UUID.randomUUID()))).andExpect(status().isForbidden());verify(references,never()).validateOrderReferences(any(),any(),any(),anyString());}
    @Test void doctorCreatesOrderUsingProfileIdsAndValidatedReferences()throws Exception{UUID appointment=UUID.randomUUID();mvc.perform(post("/api/lab/orders").header("Authorization",token(doctorUser,"DOCTOR")).contentType(MediaType.APPLICATION_JSON).content(orderJson(patientId,doctorId,appointment))).andExpect(status().isCreated()).andExpect(jsonPath("$.patientId").value(patientId.toString())).andExpect(jsonPath("$.doctorId").value(doctorId.toString())).andExpect(jsonPath("$.status").value("ORDERED"));verify(references).validateOrderReferences(eq(appointment),eq(patientId),eq(doctorId),anyString());}
    @Test void doctorCannotCreateForAnotherDoctor()throws Exception{mvc.perform(post("/api/lab/orders").header("Authorization",token(doctorUser,"DOCTOR")).contentType(MediaType.APPLICATION_JSON).content(orderJson(patientId,UUID.randomUUID(),UUID.randomUUID()))).andExpect(status().isForbidden());verify(references,never()).validateOrderReferences(any(),any(),any(),anyString());}
    @Test void adminCreatesValidOrderForAnyProfiles()throws Exception{UUID appointment=UUID.randomUUID(),anyPatient=UUID.randomUUID(),anyDoctor=UUID.randomUUID();String admin=token(UUID.randomUUID(),"ADMIN");mvc.perform(post("/api/lab/orders").header("Authorization",admin).contentType(MediaType.APPLICATION_JSON).content(orderJson(anyPatient,anyDoctor,appointment))).andExpect(status().isCreated()).andExpect(jsonPath("$.patientId").value(anyPatient.toString())).andExpect(jsonPath("$.doctorId").value(anyDoctor.toString()));verify(references).validateOrderReferences(appointment,anyPatient,anyDoctor,admin);verify(references,never()).patientProfileForCurrentUser(any(),anyString());verify(references,never()).doctorProfileForCurrentUser(any(),anyString());}
    @Test void patientMeReturnsOnlyOwnOrdersAndCannotReadAnotherPatientsOrder()throws Exception{LabOrder own=order(patientId,doctorId),other=order(UUID.randomUUID(),doctorId);String jwt=token(patientUser,"PATIENT");mvc.perform(get("/api/lab/orders/me").header("Authorization",jwt)).andExpect(status().isOk()).andExpect(jsonPath("$",hasSize(1))).andExpect(jsonPath("$[0].id").value(own.id.toString()));mvc.perform(get("/api/lab/orders/"+other.id).header("Authorization",jwt)).andExpect(status().isForbidden());}
    @Test void doctorViewsAndUpdatesOnlyTheirRecords()throws Exception{LabOrder own=order(patientId,doctorId),other=order(patientId,UUID.randomUUID());String jwt=token(doctorUser,"DOCTOR");mvc.perform(get("/api/lab/orders").header("Authorization",jwt)).andExpect(status().isOk()).andExpect(jsonPath("$",hasSize(1)));mvc.perform(put("/api/lab/orders/"+own.id).header("Authorization",jwt).contentType(MediaType.APPLICATION_JSON).content("{\"status\":\"COLLECTED\"}" )).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("COLLECTED"));mvc.perform(put("/api/lab/orders/"+other.id).header("Authorization",jwt).contentType(MediaType.APPLICATION_JSON).content("{\"status\":\"COLLECTED\"}" )).andExpect(status().isForbidden());}
    @Test void doctorCreatesOneResultPerOwnOrderAndPatientCanReadIt()throws Exception{LabOrder order=order(patientId,doctorId);String doctor=token(doctorUser,"DOCTOR");mvc.perform(post("/api/lab/results").header("Authorization",doctor).contentType(MediaType.APPLICATION_JSON).content(resultJson(order.id))).andExpect(status().isCreated()).andExpect(jsonPath("$.patientId").value(patientId.toString())).andExpect(jsonPath("$.abnormal").value(true));mvc.perform(post("/api/lab/results").header("Authorization",doctor).contentType(MediaType.APPLICATION_JSON).content(resultJson(order.id))).andExpect(status().isConflict());mvc.perform(get("/api/lab/results/me").header("Authorization",token(patientUser,"PATIENT"))).andExpect(status().isOk()).andExpect(jsonPath("$",hasSize(1)));}
    @Test void doctorCannotCreateResultForAnotherDoctorsOrder()throws Exception{LabOrder order=order(patientId,UUID.randomUUID());mvc.perform(post("/api/lab/results").header("Authorization",token(doctorUser,"DOCTOR")).contentType(MediaType.APPLICATION_JSON).content(resultJson(order.id))).andExpect(status().isForbidden());}
    @Test void adminCanListUpdateAndDeleteOrders()throws Exception{LabOrder order=order(patientId,doctorId);String admin=token(UUID.randomUUID(),"ADMIN");mvc.perform(get("/api/lab/orders").header("Authorization",admin)).andExpect(status().isOk()).andExpect(jsonPath("$",hasSize(1)));mvc.perform(put("/api/lab/orders/"+order.id).header("Authorization",admin).contentType(MediaType.APPLICATION_JSON).content("{\"status\":\"CANCELLED\"}" )).andExpect(status().isOk());mvc.perform(delete("/api/lab/orders/"+order.id).header("Authorization",admin)).andExpect(status().isNoContent());}
    @Test void validationAndReferenceFailureAreClean()throws Exception{String admin=token(UUID.randomUUID(),"ADMIN");mvc.perform(post("/api/lab/orders").header("Authorization",admin).contentType(MediaType.APPLICATION_JSON).content("{}" )).andExpect(status().isBadRequest()).andExpect(jsonPath("$.fields.patientId").exists());doThrow(new ApiException(HttpStatus.BAD_GATEWAY,"Clinical reference service unavailable")).when(references).validateOrderReferences(any(),any(),any(),anyString());mvc.perform(post("/api/lab/orders").header("Authorization",admin).contentType(MediaType.APPLICATION_JSON).content(orderJson(patientId,doctorId,UUID.randomUUID()))).andExpect(status().isBadGateway());}
    private LabOrder order(UUID patient,UUID doctor){LabOrder o=new LabOrder();o.patientId=patient;o.doctorId=doctor;o.appointmentId=UUID.randomUUID();o.testName="Complete blood count";o.status=LabOrderStatus.ORDERED;return orders.saveAndFlush(o);}
    private String token(UUID subject,String role){Instant now=Instant.now();return "Bearer "+Jwts.builder().subject(subject.toString()).claim("email",role.toLowerCase()+"@example.test").claim("role",role).issuedAt(Date.from(now)).expiration(Date.from(now.plusSeconds(600))).signWith(Keys.hmacShaKeyFor(SECRET.getBytes(StandardCharsets.UTF_8))).compact();}
    private String orderJson(UUID patient,UUID doctor,UUID appointment){return "{\"patientId\":\""+patient+"\",\"doctorId\":\""+doctor+"\",\"appointmentId\":\""+appointment+"\",\"testName\":\"Complete blood count\",\"instructions\":\"Fast for eight hours\"}";}
    private String resultJson(UUID order){return "{\"orderId\":\""+order+"\",\"resultSummary\":\"Elevated white blood cell count\",\"details\":\"WBC 12.1\",\"referenceRange\":\"4.5-11.0\",\"abnormal\":true}";}
}
